// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(uint256 amount, uint64 delay) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1 ether, 1e24);
        delay = uint64(bound(delay, 1, 1e9));
        Reverter actor = new Reverter();
        vm.deal(address(actor), amount);
        vm.prank(address(actor));
        c.Put{value: amount}(block.timestamp + delay);
        vm.prank(address(actor));
        bool ok;
        try c.Collect(amount) { ok = true; } catch { ok = false; }
        // Before the unlock time, Collect must not pay out; with a reverting
        // recipient this is observable because a pay-out attempt reverts.
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
